F = {}
F['fertility'] = dict(noun='fertility clinic', nouns='fertility clinics', practice='fertility clinic', hub='fertility-clinics', group='healthcare',
 regulator=["Clinics offering IVF, donor treatment, egg and embryo freezing and most other fertility treatments must be licensed by the Human Fertilisation and Embryology Authority (HFEA). The HFEA's Choose a Fertility Clinic tool shows each licensed clinic's inspection ratings, success rates and patient feedback.","Simple tests such as blood hormone checks may be offered by clinics outside HFEA licensing, but treatment involving eggs, sperm or embryos should always be with a licensed centre."],
 scenarios=["trying to conceive for a year or more without success","wanting fertility tests to understand options","single women or same-sex couples planning a family","freezing eggs or embryos for the future","needing donor eggs or donor sperm","previous unsuccessful IVF cycles","known conditions such as endometriosis or PCOS","male fertility concerns"],
 prepare=["how long you have been trying to conceive","ages of you and any partner","previous test results or treatment summaries","any known gynaecological or medical conditions","whether you may be eligible for NHS-funded treatment","whether donor treatment may be needed","how far you can travel for monitoring scans","questions about success rates for your age group"],
 questions=["Is the clinic HFEA licensed, and what are its inspection ratings?","What are your outcomes for patients of my age and situation?","What does the quoted cycle include and exclude?","Is counselling included, as the HFEA requires it to be offered?","Which add-on treatments do you recommend, and what evidence supports them?","How are monitoring scans arranged?","What are your policies for storing eggs, sperm or embryos?","Who will be my main contact through treatment?"],
 fees=["Fertility treatment is often quoted per cycle, but medication, tests, embryo storage and add-ons can be extra. The HFEA advises patients to ask for a full, personalised costed plan. iComply does not publish prices; the clinic quotes you, POA.","Be careful with add-ons. The HFEA rates many of them for evidence of benefit, and some have little or none."],
 red_flags=["clinics not licensed by the HFEA for the treatment","success rates that are not comparable to HFEA data","pressure to buy add-ons","unclear total costs","no offer of counselling"],
 timeline="Initial consultations and tests can often be arranged within a few weeks. A typical IVF cycle takes several weeks from start of medication to embryo transfer, and donor treatment may involve waiting for a suitable donor.",
 after="Once introduced, the clinic will book a consultation and explain tests and options. Clinical decisions are between you and your clinic. iComply does not provide medical advice.",
 faqs=[("Am I eligible for NHS fertility treatment?","Eligibility depends on local commissioning rules, including age, how long you have been trying and previous children. Ask your GP; a private clinic can also explain options."),("How do I compare clinics?","Use the HFEA's Choose a Fertility Clinic tool, which gives ratings, outcomes and patient feedback for licensed clinics.")])
F['aesthetics'] = dict(noun='aesthetic practitioner', nouns='aesthetic practitioners', practice='aesthetic clinic', hub='cosmetic-clinics', group='healthcare',
 regulator=["Anti-wrinkle injections use a prescription-only medicine, so a prescriber such as a doctor, nurse prescriber, dentist or pharmacist prescriber must assess you, normally face to face. Dermal fillers are devices rather than medicines, and the rules are tightening: the government has set out plans for a licensing scheme for non-surgical cosmetic procedures in England.","Until licensing is in force, choose a clinic carefully. Practitioners on registers such as Save Face or the JCCP, and doctors and nurses registered with the GMC or NMC, offer extra reassurance. Clinics run by regulated healthcare providers may also be registered with the CQC."],
 scenarios=["softening lines and wrinkles on the forehead or around the eyes","restoring volume to cheeks or lips","improving skin texture with peels or skin treatments","a first consultation to understand options","correcting or reviewing previous treatment","treatment for excessive sweating","a natural-looking refresh before an event","ongoing maintenance with a trusted practitioner"],
 prepare=["what you would like to change and why","photos of looks you like, if you have them","previous treatments, with dates and products if known","medical conditions, allergies and medication","whether you are pregnant or breastfeeding","any history of cold sores or skin problems","events coming up, so timing allows for recovery","questions about risks and aftercare"],
 questions=["Who will prescribe and who will treat me, and what are their qualifications?","Is the clinic registered with any regulator or accredited register?","Which products do you use, and are they licensed?","What are the risks, and how do you manage complications?","What aftercare and review appointments are included?","Can I have a cooling-off period after the consultation?","How long will results last?","What happens if I am unhappy with the result?"],
 fees=["Prices vary with the treatment, the product and the practitioner's training. Reputable clinics give a consultation before any treatment and a clear written quote. iComply does not publish prices; the clinic quotes you, POA.","Be wary of very cheap deals and group offers. They can mean unlicensed products or rushed consultations."],
 red_flags=["no face-to-face consultation before prescribed treatment","treatment offered at parties or in unsuitable premises","products that cannot be named or traced","no plan for complications","pressure to book on the day"],
 timeline="Consultations are often available within a week. Many clinics recommend a gap between consultation and treatment to give you time to decide. Results from anti-wrinkle injections usually develop over about two weeks.",
 after="Once introduced, the clinic will book a consultation to assess suitability. Treatment and aftercare are the clinic's responsibility. iComply does not provide medical advice.",
 faqs=[("Are under-18s allowed to have these treatments?","In England it is illegal to give Botox-type injections or dermal fillers for cosmetic purposes to under-18s."),("How do I know a product is genuine?","Ask the practitioner to name the product and show the packaging. Reputable clinics are happy to do so.")])
F['cosmetic_surgery'] = dict(noun='cosmetic surgeon', nouns='cosmetic surgeons', practice='cosmetic surgery provider', hub='cosmetic-clinics', group='healthcare',
 regulator=["Cosmetic surgery should be carried out by a surgeon on the GMC's specialist register, usually in plastic surgery or a related specialty, in a hospital or clinic registered with the CQC (or the equivalent regulator outside England). Many surgeons are members of BAAPS or BAPRAS, and the Royal College of Surgeons offers a cosmetic surgery certification.","The GMC requires doctors offering cosmetic interventions to give patients time to reflect before agreeing to surgery, and not to use high-pressure sales. Your consultation should be with the surgeon who will operate."],
 scenarios=["changing breast size or shape after weight loss or pregnancy","eyelid surgery for heavy or drooping lids","facial rejuvenation such as a facelift","body contouring after major weight loss","hair restoration with a transplant","revision of a previous procedure","a second opinion before deciding","planning recovery around work and family"],
 prepare=["what you want to change and what result you hope for","your medical history, medication and smoking status","previous surgery or procedures","photos that illustrate your goals","time you can take off work for recovery","who can support you at home after surgery","whether you are considering treatment abroad","questions about risks and revision policies"],
 questions=["Are you on the GMC specialist register, and how often do you perform this operation?","Where will the operation take place, and is it CQC registered?","What are the risks and the likely recovery time?","What does the package include, such as aftercare and revision?","Will I see you, the surgeon, at every stage?","How long should I wait between consultation and surgery?","What happens if there is a complication at night?","Can I see before-and-after photos of your own patients?"],
 fees=["Cosmetic surgery is usually quoted as a package covering the surgeon, anaesthetist, hospital stay and some follow-up. What is included varies a great deal. iComply does not publish prices; the provider quotes you, POA.","Check whether revision surgery and treatment of complications are included, and be cautious about finance offers or discounts that create pressure to decide quickly."],
 red_flags=["a consultation with a salesperson rather than the surgeon","discounts for booking quickly","no cooling-off period","a surgeon not on the GMC specialist register","unclear aftercare, especially for treatment abroad"],
 timeline="After a first consultation, most reputable surgeons recommend at least two weeks before you commit to surgery. Recovery varies by procedure, from a week or two for minor surgery to several weeks for major operations.",
 after="Once introduced, the provider will arrange a consultation with the surgeon. Clinical responsibility sits with the surgeon and hospital. iComply does not provide medical advice.",
 faqs=[("Is surgery abroad cheaper and safe?","Costs can be lower, but follow-up care and complications can be harder to manage. If you are considering it, ask how aftercare and complications will be handled once you are home."),("What is a cooling-off period?","Time between your consultation and agreeing to surgery. It gives you space to reflect and ask further questions, and reputable surgeons insist on it.")])
F['mortgage'] = dict(noun='mortgage broker', nouns='mortgage brokers', practice='mortgage brokerage', hub='mortgage-advisors', group='finance',
 regulator=["Mortgage advice is regulated by the Financial Conduct Authority (FCA). Any broker or adviser you use should be authorised, or be an appointed representative of an authorised firm, and you can check this on the FCA register. Advisers typically hold a qualification such as CeMAP.","Brokers must tell you whether they search the whole of the market or a limited panel of lenders, and how they are paid, whether by lender commission, a fee, or both. If something goes wrong, you can complain to the firm and then to the Financial Ombudsman Service."],
 scenarios=["a first-time buyer working out how much they can borrow","moving home and porting or replacing a mortgage","a remortgage as a fixed rate ends","buying to let as a landlord","self-employed or contractor income","a past credit problem","bridging or development finance for a project","a mortgage for a later-life or expat situation"],
 prepare=["your income details, such as payslips or accounts","your deposit or equity amount","current debts and credit commitments","your credit history, including any problems","the property type and price range","when your current deal ends, if remortgaging","your plans for the next few years","any questions about protection insurance"],
 questions=["Are you FCA authorised, and can I see your entry on the register?","Do you search the whole of the market or a panel of lenders?","How are you paid: fee, commission or both?","When is any fee payable, and is it refundable?","Can you explain the total cost of each option, not just the rate?","How will you handle my application with the lender?","What happens if my circumstances change before completion?","Do you also advise on protection insurance?"],
 fees=["Some brokers charge a fee, some are paid only by the lender, and some combine both. They must explain this before they give advice. iComply does not publish fees; the broker tells you their charges, POA.","Ask when any fee is payable and whether it is refundable if the mortgage does not go ahead."],
 red_flags=["a firm or adviser not on the FCA register","no explanation of how the broker is paid","pressure to borrow more than you are comfortable with","advice to give inaccurate information to a lender","fees requested up front with no written terms"],
 timeline="An initial conversation can often happen within a few days. An agreement in principle can follow quickly, and a full mortgage offer usually takes a few weeks once the application and valuation are complete. Start a remortgage review several months before your deal ends.",
 after="Once introduced, the broker will gather your information, check affordability and recommend suitable options. Advice and responsibility for it sit with the authorised firm. iComply does not give mortgage advice. Your home may be repossessed if you do not keep up repayments on your mortgage.",
 faqs=[("Is a broker better than going to my bank?","A broker can compare many lenders and may find options your bank does not offer. Your bank can only offer its own products. Either can suit you; a broker gives you a wider view."),("Will speaking to a broker affect my credit score?","An initial conversation does not. Formal applications usually involve a credit search, and the broker should tell you before that happens.")])
